#!/usr/bin/env bash
# flake.nix's devShell (and Triton's TRITON_LIBCUDA_PATH) look for the host
# driver (libcuda.so.1 and friends) in /run/opengl-driver/lib, the NixOS
# convention. Where it ends up in the container depends on how the host
# passes the GPU through:
#
#  * NixOS host, CDI (`--device nvidia.com/gpu=all`, what devcontainer.json
#    uses): the host's CDI spec already bind-mounts its /run/opengl-driver in,
#    read-only. Nothing to do -- and nothing CAN be done, it's read-only.
#  * Other distros (CDI generated by `nvidia-ctk cdi generate`, or the legacy
#    `nvidia` runtime): the driver is injected into the distro libdir, so link
#    just the driver libraries across. (Not the whole libdir: that would put
#    Ubuntu's glibc on the search path of Nix binaries built against Nix's.)
set -euo pipefail

dst=/run/opengl-driver/lib
src=/usr/lib/$(uname -m)-linux-gnu

if [ -e "$dst/libcuda.so.1" ]; then
  echo "link-nvidia-driver: host driver already at $dst"
  exit 0
fi

if [ -L "$dst/libcuda.so.1" ]; then
  # Present but dangling: a NixOS host's CDI mounts its driver store path
  # under /nix/store, and something mounted over /nix hid it (see the
  # `mounts` comment in devcontainer.json).
  echo "link-nvidia-driver: WARNING: $dst/libcuda.so.1 -> $(readlink "$dst/libcuda.so.1") is dangling;" \
    "is a volume mounted over /nix? The GPU will be unusable." >&2
  exit 0
fi

if ! compgen -G "$src/libcuda.so*" >/dev/null; then
  echo "link-nvidia-driver: no NVIDIA driver injected, skipping (no GPU passed through?)"
  exit 0
fi

sudo mkdir -p "$dst"
for f in "$src"/libcuda.so* "$src"/libnvidia-*.so* "$src"/libnvcuvid.so*; do
  [ -e "$f" ] && sudo ln -sf "$f" "$dst/"
done
echo "link-nvidia-driver: linked host driver into $dst"
